import java.io.*;
import java.util.*;

public class B {
    static boolean inside;
    static boolean wordStart;
    static int maxOutLen;
    static int curOutLen;
    static int insideWordCount;

    public static void main(String[] args) throws IOException {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        while (in.hasNext()) {
            int n = in.nextInt();
            String s = in.next();
            reset();
            for (char c : s.substring(0, n).toCharArray()) {
                process(c);
            }
            out.println(maxOutLen + " " + insideWordCount);
        }
        out.flush();
    }

    static void process(char c) {
        if (c == '(') {
            inside = true;
            wordStart = true;
            curOutLen = 0;
        } else if (c == ')') {
            inside = false;
            curOutLen = 0;
        } else if (!inside) {
            if (c == '_') {
                curOutLen = 0;
            } else {
                curOutLen++;
                if (curOutLen > maxOutLen) {
                    maxOutLen = curOutLen;
                }
            }
        } else {
            if (c == '_') {
                wordStart = true;
            } else if (wordStart) {
                insideWordCount++;
                wordStart = false;
            }
        }
    }

    static void reset() {
        inside = false;
        wordStart = true;
        maxOutLen = 0;
        curOutLen = 0;
        insideWordCount = 0;
    }

    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;
        FastScanner(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }
        boolean hasNext() {
            try {
                return br.ready();
            } catch (IOException e) {
                return false;
            }
        }
        String next() {
            while (st == null || !st.hasMoreTokens()) {
                String line;
                try {
                    line = br.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
        int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
